--
-- Init core_template
--

INSERT INTO core_template VALUES ('extend_follow','\r\n<#if !followClosed>\r\n    <#if canDeleteFollow>\r\n        <div>\r\n            <p>#i18n{module.extend.follow.extender.closed.label} :</p>\r\n            <form action="jsp/site/plugins/extend/modules/follow/DoCancelFollow.jsp" method="post">\r\n                <input type="hidden" name="idExtendableResource" value="${idExtendableResource!}" />\r\n                <input type="hidden" name="extendableResourceType" value="${extendableResourceType!}" />\r\n                <input type="hidden" name="token" value="${cancelFollowToken!}" />\r\n                <button type="submit">#i18n{module.extend.follow.extender.cancelFollow.label}</button>\r\n            </form>\r\n        </div>\r\n    </#if>\r\n    <#if show == "all" || show == "actionFollow">\r\n        <#if canFollow && !canDeleteFollow>\r\n            <div>\r\n                <form action="jsp/site/plugins/extend/modules/follow/DoFollow.jsp" method="post">\r\n                    <input type="hidden" name="idExtendableResource" value="${idExtendableResource!}" />\r\n                    <input type="hidden" name="extendableResourceType" value="${extendableResourceType!}" />\r\n                    <input type="hidden" name="followValue" value="1" />\r\n                    <input type="hidden" name="token" value="${followToken!}" />\r\n                    <button type="submit">#i18n{module.extend.follow.extender.doFollow.label}</button>\r\n                </form>\r\n            </div>\r\n        </#if>\r\n    </#if>\r\n</#if>\r\n<#if follow??><p>#i18n{module.extend.follow.extender.count.label} : ${follow.followCount}</p></#if>');
